import * as React from "react"

function BackgroundGradientChangingButton({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="background-gradient-changing-button"
      className={className}
      {...props}
    >
      <button className="bg-gradient-to-r from-blue-500 to-red-500 text-white px-4 py-2 text-xl rounded font-medium focus ring-black ring-opacity-10 gradient element-to-rotate">Gradient Button</button>
    </div>
  )
}

export { BackgroundGradientChangingButton }
